function validate([head, m, n]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 10000) return 'The list needs 1 to 10^4 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each node value is an integer from 1 to 10^6.';
  if (!Number.isInteger(m) || m < 1 || m > 1000) return 'm is an integer from 1 to 1000.';
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is an integer from 1 to 1000.';
  return null;
}

