  const values = [];
  for (let p = head; p; p = p.next) values.push(p.val);
  const survivors = values.filter((_, index) => index % (m + n) < m);
  let result = null;
  for (let i = survivors.length - 1; i >= 0; i--) result = new ListNode(survivors[i], result);
