function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const length = pick(1500, 2000);
    const head = Array.from({ length }, () => pick(1, 1000000));
    const mode = rand();
    const m = mode < 0.4 ? pick(1, 10) : pick(1, 1000);
    const n = mode < 0.7 ? pick(1, 10) : pick(1, 1000);
    return [head, m, n];
  }
  const length = pick(1, 12);
  const high = rand() < 0.5 ? 9 : 1000000;
  const head = Array.from({ length }, () => pick(1, high));
  const m = rand() < 0.1 ? pick(1, 1000) : pick(1, 5);
  const n = rand() < 0.1 ? pick(1, 1000) : pick(1, 5);
  return [head, m, n];
}
